<script setup lang="ts">
import {userErrorMessage,isSessionError} from './diagnostics.js'
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {messages} from './modelhub/messages'
import {request as api,encode,fileSize,schedulerRequest} from './modelhub/client'
import ModelHubGuide from './modelhub/Guide.vue'
import ModelLifecycle from './ModelLifecycle.vue'
const props=defineProps<{locale:string,t:(text:string)=>string,docsOnly?:boolean}>()
const stateLabels:Record<string,string>={all:'全部',ready:'就绪',pulling:'下载中',failed:'失败',deleting:'删除中',PENDING:'等待中',DOWNLOADING:'下载中',VERIFYING:'校验中',READY:'就绪',FAILED:'失败'}
function t(text:string){text=stateLabels[text]||text;return props.locale==='zh-CN'?text:messages[text]?.[props.locale==='en'?1:0]||props.t(text)}
const tab=ref(props.docsOnly?'guide':'models'),busy=ref(false),error=ref(''),notice=ref('')
const models=ref<any[]>([]),tasks=ref<any[]>([]),runtimes=ref<any[]>([]),services=ref<any[]>([]),aliases=ref<any[]>([]),bindings=ref<any[]>([])
const budgets=ref<any[]>([]),budgetDraft=ref<any>(null),budgetConfirm=ref(false)
const resourceFields=[{key:'cpu_millicores',label:'CPU 毫核'},{key:'memory_mib',label:'内存 MiB'},{key:'gpu_slots',label:'GPU 槽位'},{key:'gpu_memory_mib',label:'显存 MiB'}]
const limitFields=[{key:'max_tokens',label:'最大输出 token'},{key:'options.num_ctx',label:'上下文长度'},{key:'options.num_predict',label:'单次预测 token'},{key:'options.num_thread',label:'线程数'},{key:'options.num_batch',label:'批大小'},{key:'options.num_gpu',label:'GPU 层数上限'}]
const budgetModes=[{id:'calibrated',label:'手动预算'},{id:'direct',label:'不做限制（直接放行）'}]
const source=ref('ollama'),modelId=ref(''),displayName=ref(''),scope=ref('full'),append=ref(false),listing=ref<any>(null),selected=ref<string[]>([]),fileQuery=ref(''),modelQuery=ref(''),status=ref('all'),localFiles=ref<any>(null),versionChecks=ref<Record<string,any>>({})
const filtered=computed(()=>models.value.filter(m=>(status.value==='all'||m.status===status.value)&&`${m.name} ${m.model_id}`.toLowerCase().includes(modelQuery.value.toLowerCase())))
const visibleFiles=computed(()=>listing.value?.files.filter((f:any)=>f.path.toLowerCase().includes(fileQuery.value.toLowerCase()))||[])
const selectedBytes=computed(()=>listing.value?.files.reduce((sum:number,f:any)=>sum+(selected.value.includes(f.path)?f.size||0:0),0)||0)
const runtimeModels=ref<Record<string,string>>({}),actions=ref(new Set<string>())
const archiveFile=ref<File|null>(null),importSource=ref('hf'),importId=ref(''),remoteRepo=ref(''),importName=ref(''),importVersion=ref(''),replaceExisting=ref(false)
const aliasName=ref(''),aliasTarget=ref(''),containerId=ref(''),containerModel=ref(''),containerCount=ref(1)
const repositoryModel=ref(''),servedModel=ref('')
const serviceForm=ref({service_id:'',name:'',kind:'ollama',base_url:'',gateway_url:'',role:'generate'}),contract=ref(JSON.stringify({health_path:'/health',models_path:'/v1/models',running_models_path:'/v1/models',runtime_status_path:null,metrics_path:null,start_model_path:null,stop_model_path:null,model_action_status_path:null},null,2))
let timer:ReturnType<typeof setInterval>|undefined,revision=0,disposed=false
async function act(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await work()}catch(e){error.value=userErrorMessage(e)}finally{busy.value=false}}
async function refreshModels(){models.value=await api('/api/v1/models?status=all');try{budgets.value=(await schedulerRequest('/model-budgets')).items||[]}catch(e){if(!isSessionError(e))budgets.value=[]}}
function budgetKey(id:string){const name=(id||'').replace(/^ollama:\/\//,'');const leaf=name.split('/').pop()||'';return leaf.includes(':')?name:`${name}:latest`}
function budgetsFor(model:any){const key=budgetKey(model.model_id);return budgets.value.filter((budget:any)=>budgetKey(budget.repository_model_id)===key)}
function resourcesLabel(resources:any){if(!resources)return '—';return `${(resources.cpu_millicores/1000).toFixed(1)} vCPU · ${resources.memory_mib} MiB · ${resources.gpu_slots} GPU · ${resources.gpu_memory_mib} MiB`}
function budgetModeLabel(budget:any){return budget.mode==='direct'?'直接放行':budget.calibrated?'已校准':'自动估算'}
function openBudget(budget:any){budgetDraft.value={model_id:budget.model_id,mode:budget.mode==='direct'?'direct':'calibrated',resources:{...(budget.resources||budget.default_resources||{cpu_millicores:0,memory_mib:0,gpu_slots:0,gpu_memory_mib:0})},limits:{...(budget.limits||budget.default_limits||{})},default:budget.default_resources};budgetConfirm.value=false}
async function saveBudget(){await act(async()=>{const draft=budgetDraft.value;if(draft.mode==='direct'){await schedulerRequest('/model-budgets/calibrate',{model_id:draft.model_id,mode:'direct'})}else{const resources=draft.resources,limits=draft.limits;if(resources.cpu_millicores<=0||resources.memory_mib<=0)throw Error(t('CPU 和内存预算必须大于 0'));if(resources.gpu_memory_mib>0&&resources.gpu_slots<=0)throw Error(t('设置显存预算时必须设置 GPU 槽位'));for(const field of limitFields){const value=Number(limits[field.key]);if(!Number.isInteger(value)||value<0||(field.key!=='options.num_gpu'&&value===0))throw Error(t('运行上限必须是正数'))}await schedulerRequest('/model-budgets/calibrate',{model_id:draft.model_id,mode:'calibrated',resources,limits})}budgetDraft.value=null;notice.value=t(draft.mode==='direct'?'该模型已直接放行，不再参与调度准入':'模型预算已校准');await refreshModels()})}
async function restoreBudget(budget:any){if(!confirm(`${t('恢复默认预算')} ${budget.model_id}?`))return;await act(async()=>{await schedulerRequest('/model-budgets/restore',{model_id:budget.model_id});notice.value=t('已恢复默认预算');await refreshModels()})}
async function refreshTasks(){tasks.value=await api('/api/v1/tasks')}
async function refreshRuntime(){await refreshModels();const [builtins,registered]=await Promise.all([api('/api/v1/ollama/runtime'),api('/api/v1/inference-services')]);if(disposed)return;runtimes.value=builtins.runtimes;services.value=await Promise.all(registered.map(async(s:any)=>{try{return {...s,...await api(`/api/v1/inference-services/${encode(s.service_id)}`)}}catch(e){if(isSessionError(e))throw e;return {...s,healthy:false,error:t('服务不可达'),models:[]}}}))}
async function refresh(){if(tab.value==='models')await refreshModels();else if(tab.value==='tasks')await refreshTasks();else if(tab.value==='runtime')await refreshRuntime();else if(tab.value==='references'){[aliases.value,bindings.value]=await Promise.all([api('/api/v1/aliases'),api('/api/v1/containers')])}}

function invalidate(){revision++;listing.value=null;selected.value=[]}
watch([source,modelId],invalidate)
async function loadFiles(){const current=++revision;await act(async()=>{const data=await api(`/api/v1/models/repository-files?source=${source.value}&model_id=${encode(modelId.value.trim())}`);if(current===revision){listing.value=data;selected.value=[]}})}
async function pull(){await act(async()=>{if(!modelId.value.trim())throw Error(t('请输入模型名称'));if(source.value!=='ollama'&&scope.value==='selected'&&!selected.value.length)throw Error(t('请选择要下载的文件'));const created=await api('/api/v1/models/pull',{source:source.value,model_id:`${source.value}://${modelId.value.trim().replace(/^(ollama|hf|ms):\/\//,'')}`,name:displayName.value||null,...(source.value!=='ollama'&&scope.value==='selected'?{files:selected.value,append:append.value}:{})});notice.value=t('下载任务已创建: ')+created.task_id;tab.value='tasks';await refreshTasks()})}
function addFiles(model:any){source.value=model.source;modelId.value=model.model_id.replace(/^(hf|ms):\/\//,'');displayName.value=model.name;scope.value='selected';append.value=true;tab.value='pull';invalidate()}
async function inspectFiles(model:any){await act(async()=>{localFiles.value=await api(`/api/v1/models/files?model_id=${encode(model.model_id)}`)})}
async function checkOne(model:any){await act(async()=>{versionChecks.value[model.model_id]=await api(`/api/v1/models/check-update?model_id=${encode(model.model_id)}`,{})})}
async function checkAll(){await act(async()=>{const data=await api('/api/v1/models/check-updates',{});versionChecks.value=Object.fromEntries(data.results.map((v:any)=>[v.model_id,v]))})}
async function update(model:any){await act(async()=>{await api(`/api/v1/models/update?model_id=${encode(model.model_id)}`,{});tab.value='tasks';await refreshTasks()})}
async function removeModel(model:any){if(!confirm(`${t('确认删除模型')} ${model.name}?`))return;await act(async()=>{await api(`/api/v1/models?model_id=${encode(model.model_id)}`,undefined,'DELETE');await refreshModels()})}
async function syncModels(){await act(async()=>{const data=await api('/api/v1/models/sync',{});notice.value=`${t('同步完成')} · ${data.synced}`;await refreshModels()})}
async function taskAction(task:any,action:string){if(action==='delete'&&!confirm(t('确认删除任务记录（不会删除模型）')))return;await act(async()=>{await api(`/api/v1/tasks/${encode(task.task_id)}${action==='delete'?'':`/${action}`}`,action==='delete'?undefined:{},action==='delete'?'DELETE':'POST');await refreshTasks()})}
async function clean(){await act(async()=>{const data=await api('/api/v1/models/cleanup',{});notice.value=`${t('清理完成')} · ${fileSize(data.freed_bytes)}`})}
async function importArchive(){await act(async()=>{if(!archiveFile.value)throw Error(t('请选择压缩包'));const form=new FormData();form.set('archive',archiveFile.value);Object.entries({source:importSource.value,model_id:importId.value,remote_repo:remoteRepo.value,name:importName.value,version:importVersion.value,replace_existing:String(replaceExisting.value)}).forEach(([k,v])=>form.set(k,v));await api('/api/v1/models/import-archive',form);notice.value=t('导入成功');tab.value='models';await refreshModels()})}
async function modelAction(service:any,model:string,start:boolean){if(!model)return;const key=`${service.service_id}/${model}`;if(actions.value.has(key))return;actions.value.add(key);try{const result=await api(`/api/v1/inference-services/${encode(service.service_id)}/models/${start?'start':'stop'}`,{model,mode:service.role,keep_alive:service.keep_alive||'-1m',confirm_timeout_seconds:8});notice.value=result.confirmed?t('操作已确认'):t('请求已接受，尚未确认完成');await refreshRuntime()}catch(e){error.value=userErrorMessage(e)}finally{actions.value.delete(key)}}
async function registerService(){await act(async()=>{await api('/api/v1/inference-services/register',{...serviceForm.value,...(repositoryModel.value?{metadata:{model_bindings:{[servedModel.value]:repositoryModel.value}}}:{}),gateway_url:serviceForm.value.gateway_url||null,...(serviceForm.value.kind==='ollama'?{}:{api_contract:JSON.parse(contract.value)})});notice.value=t('服务已注册');await refreshRuntime()})}
async function deleteService(service:any){if(!confirm(`${t('删除服务注册')} ${service.name}?`))return;await act(async()=>{await api(`/api/v1/inference-services/${encode(service.service_id)}`,undefined,'DELETE');await refreshRuntime()})}
async function createAlias(){await act(async()=>{await api('/api/v1/aliases',{alias:aliasName.value,target_model_id:aliasTarget.value});aliasName.value='';await refresh()})}
async function deleteAlias(alias:string){await act(async()=>{await api(`/api/v1/aliases/${encode(alias)}`,undefined,'DELETE');await refresh()})}
async function bind(){await act(async()=>{await api('/api/v1/containers/bind',{container_id:containerId.value,model_id:containerModel.value,ref_count:containerCount.value});await refresh()})}
async function unbind(id:string){await act(async()=>{await api('/api/v1/containers/unbind',{container_id:id},'DELETE');await refresh()})}
async function copy(value:string){try{await navigator.clipboard.writeText(value);notice.value=t('已复制')}catch{error.value=t('复制失败')}}
watch(()=>props.locale,()=>{notice.value=''})
watch(tab,()=>{error.value='';refresh().catch(e=>{error.value=userErrorMessage(e)})})
onMounted(()=>{refresh().catch(e=>{error.value=userErrorMessage(e)});timer=setInterval(()=>{if(!busy.value&&['tasks','runtime'].includes(tab.value))refresh().catch(()=>{})},3000)})
onUnmounted(()=>{disposed=true;clearInterval(timer)})
</script>
<template>
 <div class="model-hub">
  <nav v-if="!docsOnly" class="hub-tabs" :aria-label="t('模型管理')"><button v-for="item in [{id:'models',label:'本地模型'},{id:'pull',label:'拉取模型'},{id:'import',label:'压缩包导入'},{id:'tasks',label:'下载任务'},{id:'runtime',label:'推理服务'},{id:'lifecycle',label:'模型接入状态'},{id:'references',label:'别名与引用'}]" :key="item.id" :class="{current:tab===item.id}" @click="tab=item.id">{{t(item.label)}}</button></nav>
  <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="hub-notice" role="status">{{notice}}</p>
  <template v-if="tab==='models'">
   <section class="panel hub-toolbar"><input v-model="modelQuery" :placeholder="t('搜索模型')"><select v-model="status"><option v-for="state in ['all','ready','pulling','failed','deleting']" :key="state" :value="state">{{t(state)}}</option></select><button :disabled="busy" @click="syncModels">{{t('同步磁盘')}}</button><button :disabled="busy" @click="checkAll">{{t('检查全部更新')}}</button><button @click="tab='pull'">{{t('拉取模型')}}</button><button @click="tab='import'">{{t('压缩包导入')}}</button></section>
   <div class="hub-cards"><article v-for="model in filtered" :key="model.model_id" class="panel hub-card"><div class="hub-card-title"><h3>{{model.name}}</h3><span class="hub-state" :class="model.status">{{t(model.status)}}</span></div><code>{{model.model_id}}</code><p>{{model.source}} · {{fileSize(model.size)}} · {{model.version||'—'}}</p><label>{{t('共享访问路径')}}</label><div class="hub-path"><code>{{model.access_path||model.path}}</code><button @click="copy(model.access_path||model.path)">{{t('复制')}}</button></div><p v-if="model.files">{{t('已选择文件')}}: {{model.files.length}} · {{t('READY 仅表示所选范围完成')}}</p><p v-if="versionChecks[model.model_id]">{{versionChecks[model.model_id].error||t(versionChecks[model.model_id].has_update?'有可用更新':'已是最新版本')}} {{versionChecks[model.model_id].latest_version}}</p><div v-if="budgetsFor(model).length" class="hub-budget"><div class="hub-budget-head"><strong>{{t('模型预算')}}</strong><small>{{t('调度器按预算为模型分配 CPU、内存和 GPU')}}</small></div><div v-for="budget in budgetsFor(model)" :key="budget.model_id" class="hub-budget-row"><div class="hub-budget-info"><span>{{budget.role}}</span><span class="hub-state" :class="budget.mode==='direct'?'pulling':budget.calibrated?'downloaded':'ready'">{{t(budgetModeLabel(budget))}}</span><code>{{budget.mode==='direct'?t('跳过调度准入，请求直接发送到 Ollama'):resourcesLabel(budget.resources)}}</code><small v-if="budget.mode!=='direct'&&budget.limits" class="hub-budget-limits">{{t('上下文')}} {{budget.limits['options.num_ctx']}} · {{t('最大输出')}} {{budget.limits.max_tokens}} token</small></div><div class="hub-actions"><button :disabled="busy" @click="openBudget(budget)">{{t('校准预算')}}</button><button v-if="budget.mode!=='automatic'" :disabled="busy" @click="restoreBudget(budget)">{{t('恢复默认')}}</button></div></div></div><div class="hub-actions"><button v-if="model.source!=='ollama'" :disabled="busy" @click="inspectFiles(model)">{{t('查看文件')}}</button><button v-if="model.source!=='ollama'&&model.status==='ready'" @click="addFiles(model)">{{t('追加文件')}}</button><button :disabled="busy||model.status!=='ready'" @click="checkOne(model)">{{t('检查更新')}}</button><button :disabled="busy||model.status!=='ready'" @click="update(model)">{{t('更新模型')}}</button><button @click="tab='lifecycle'">{{t('查看接入状态')}}</button><button class="danger" :disabled="busy||model.status==='pulling'" @click="removeModel(model)">{{t('删除')}}</button></div></article></div>
   <p v-if="!filtered.length" class="panel hub-empty">{{t('暂无本地模型')}}</p>
   <section v-if="localFiles" class="panel hub-card"><div class="hub-card-title"><h3>{{localFiles.model_id}} · {{t('本地文件')}}</h3><button @click="localFiles=null">{{t('关闭')}}</button></div><div class="hub-file-list"><div v-for="file in localFiles.files" :key="file.path"><code>{{file.path}}</code><span>{{fileSize(file.size)}}</span></div></div></section>
  </template>
  <section v-if="tab==='pull'" class="panel hub-card"><h2>{{t('拉取新模型')}}</h2><form @submit.prevent="pull"><div class="hub-form"><label>{{t('平台')}}<select v-model="source"><option value="ollama">Ollama</option><option value="hf">HuggingFace</option><option value="ms">ModelScope</option></select></label><label>{{t('模型名称')}}<input v-model="modelId" required :placeholder="source==='ollama'?'qwen3.5:2b':'org/repo'"></label><label>{{t('显示名称')}}<input v-model="displayName"></label></div>
   <div v-if="source!=='ollama'" class="hub-scope"><label><input v-model="scope" type="radio" value="full">{{t('下载完整仓库')}}</label><label><input v-model="scope" type="radio" value="selected">{{t('选择文件下载')}}</label><label v-if="scope==='selected'"><input v-model="append" type="checkbox">{{t('追加到已有模型（保留已下载文件）')}}</label><button type="button" :disabled="busy||!modelId" @click="loadFiles">{{t('读取仓库文件')}}</button></div>
   <template v-if="listing&&source!=='ollama'"><div class="hub-toolbar"><input v-model="fileQuery" :placeholder="t('搜索文件')"><button type="button" @click="selected=[...new Set([...selected,...visibleFiles.filter((f:any)=>!f.downloaded).map((f:any)=>f.path)])]">{{t('选择搜索结果')}}</button><button type="button" @click="selected=[]">{{t('清空选择')}}</button><span>{{selected.length}} · {{fileSize(selectedBytes)}}</span></div><div class="hub-file-list"><label v-for="file in visibleFiles" :key="file.path"><input v-if="scope==='selected'" v-model="selected" type="checkbox" :value="file.path" :disabled="file.downloaded&&append"><code>{{file.path}}</code><span>{{fileSize(file.size)}}</span><small v-if="file.downloaded">{{t('已下载')}}</small></label></div></template>
   <p>{{t('READY 仅表示所选范围完成')}}</p><button class="primary" :disabled="busy">{{t('开始下载')}}</button></form><div class="hub-actions"><button v-for="preset in ['qwen3.5:2b','bge-m3','qllama/bge-reranker-v2-m3:q8_0']" :key="preset" @click="source='ollama';modelId=preset">{{preset}}</button></div></section>
  <section v-if="tab==='import'" class="panel hub-card"><h2>{{t('压缩包导入')}}</h2><form @submit.prevent="importArchive"><div class="hub-form"><label>{{t('平台')}}<select v-model="importSource"><option value="hf">HuggingFace</option><option value="ms">ModelScope</option></select></label><label>{{t('压缩包')}}<input type="file" accept=".zip,.tar,.gz,.tgz,.bz2,.tbz2,.xz,.txz" required @change="archiveFile=($event.target as HTMLInputElement).files?.[0]||null"></label><label>{{t('模型 ID')}}<input v-model="importId" placeholder="local/my-model"></label><label>{{t('远端仓库（可选）')}}<input v-model="remoteRepo" placeholder="org/repo"></label><label>{{t('显示名称')}}<input v-model="importName"></label><label>{{t('版本')}}<input v-model="importVersion"></label></div><p>{{t('支持 zip / tar / tar.gz / tar.bz2 / tar.xz / tgz，解压成功后才切换当前版本。')}}</p><label class="hub-check"><input v-model="replaceExisting" type="checkbox">{{t('替换已有模型')}}</label><button class="primary" :disabled="busy">{{busy?t('导入中…'):t('导入模型')}}</button></form></section>
  <template v-if="tab==='tasks'"><section class="hub-toolbar"><button :disabled="busy" @click="act(refreshTasks)">{{t('刷新')}}</button><button :disabled="busy" @click="clean">{{t('清理临时文件')}}</button></section><article v-for="task in tasks" :key="task.task_id" class="panel hub-card"><div class="hub-card-title"><h3>{{task.model_id}}</h3><span class="hub-state" :class="task.phase.toLowerCase()">{{t(task.phase)}}</span></div><progress :value="task.progress" max="1"></progress><p>{{(task.progress*100).toFixed(1)}}% · {{fileSize(task.speed)}}/s · ETA {{task.eta?Math.ceil(task.eta)+'s':'—'}}</p><code>{{task.task_id}}</code><p v-if="task.files">{{task.files.length}} {{t('个文件')}} · {{task.append?t('追加文件'):t('选择文件下载')}}</p><p v-if="task.error_msg" class="error">{{task.error_msg}}</p><div class="hub-actions"><button v-if="!['READY','FAILED'].includes(task.phase)" :disabled="busy" @click="taskAction(task,'cancel')">{{t('取消')}}</button><button v-if="task.phase==='FAILED'" :disabled="busy" @click="taskAction(task,'retry')">{{t('重试')}}</button><button :disabled="busy" @click="taskAction(task,'delete')">{{t('删除记录')}}</button><button @click="copy(task.task_id)">{{t('复制任务 ID')}}</button></div></article><p v-if="!tasks.length" class="panel hub-empty">{{t('暂无下载任务')}}</p></template>
  <template v-if="tab==='runtime'"><div class="hub-toolbar"><button :disabled="busy" @click="act(refreshRuntime)">{{t('刷新')}}</button></div><h2>{{t('Ollama 实例')}}</h2><div class="hub-cards"><article v-for="service in [...runtimes,...services.filter(s=>s.kind==='ollama')]" :key="service.service_id" class="panel hub-card"><div class="hub-card-title"><h3>{{service.name}}</h3><span class="hub-state" :class="service.healthy?'ready':'failed'">{{t(service.healthy?'在线':'离线')}}</span></div><p>{{service.role}} · {{typeof service.version==='object'?service.version?.version:service.version||'—'}}</p><code>{{service.base_url}}</code><p><code>{{service.gateway_url}}</code></p><p>{{t('槽位')}} {{service.active_slots??'—'}} / {{service.total_slots??'—'}} · {{t('上下文')}} {{service.context_length??'—'}}</p><p v-if="service.error" class="error">{{service.error}}</p><div class="hub-runtime-models"><div v-for="model in service.models||[]" :key="model.name" class="hub-runtime-model"><div><strong>{{model.name}}</strong><span class="hub-state" :class="model.running?'ready':model.phase==='failed'?'failed':'downloaded'">{{t(model.running?'运行中':model.phase==='failed'?'失败':'已下载')}}</span></div><small>{{model.details?.parameter_size||model.parameter_size}} {{model.details?.quantization_level||model.quantization_level}} · {{fileSize(model.size)}} · VRAM {{fileSize(model.size_vram)}}</small><p>{{model.phase}} · {{model.active_slots??0}} / {{model.total_slots??'—'}} · {{model.tokens_per_second||model.decode_tokens_per_second||0}} token/s · Prefill {{model.prefill_tokens_per_second||0}}</p><button :disabled="actions.has(`${service.service_id}/${model.name}`)" @click="modelAction(service,model.name,!model.running)">{{t(model.running?'停止模型':'启动模型')}}</button></div></div><div class="hub-toolbar"><input v-model="runtimeModels[service.service_id]" :placeholder="service.preload_model||'model'" :aria-label="t('模型名称')"><button @click="modelAction(service,runtimeModels[service.service_id],true)">{{t('启动模型')}}</button></div><details><summary>{{t('运行指标')}}</summary><pre>{{JSON.stringify(service.metrics,null,2)}}</pre></details><button v-if="!service.metadata?.builtin" class="danger" @click="deleteService(service)">{{t('删除服务注册')}}</button></article></div>
   <h2>{{t('其他推理服务')}}</h2><div class="hub-cards"><article v-for="service in services.filter(s=>s.kind!=='ollama')" :key="service.service_id" class="panel hub-card"><div class="hub-card-title"><h3>{{service.name}}</h3><span class="hub-state" :class="service.healthy?'ready':'failed'">{{t(service.healthy?'在线':'离线')}}</span></div><code>{{service.base_url}}</code><p>{{service.kind}} · {{service.role}}</p><p v-if="service.error" class="error">{{service.error}}</p><div v-for="model in service.models||[]" :key="model.name" class="hub-runtime-model"><strong>{{model.name}}</strong><span class="hub-state" :class="model.running?'ready':'downloaded'">{{t(model.running?'运行中':'已下载')}}</span><p>{{model.phase}} · {{model.active_slots??'—'}} / {{model.total_slots??'—'}} · {{model.tokens_per_second??'—'}} token/s</p><button :disabled="actions.has(`${service.service_id}/${model.name}`)" @click="modelAction(service,model.name,!model.running)">{{t(model.running?'停止模型':'启动模型')}}</button></div><div class="hub-toolbar"><input v-model="runtimeModels[service.service_id]" :placeholder="t('模型名称')"><button @click="modelAction(service,runtimeModels[service.service_id],true)">{{t('启动模型')}}</button></div><details><summary>{{t('运行指标')}}</summary><pre>{{JSON.stringify({runtime:service.runtime_status,metrics:service.metrics,version:service.version},null,2)}}</pre></details><button class="danger" @click="deleteService(service)">{{t('删除服务注册')}}</button></article></div>
   <details class="panel hub-card"><summary>{{t('注册或更新推理服务')}}</summary><form @submit.prevent="registerService"><div class="hub-form"><label>Service ID<input v-model="serviceForm.service_id" required></label><label>{{t('名称')}}<input v-model="serviceForm.name" required></label><label>{{t('类型')}}<select v-model="serviceForm.kind"><option value="ollama">Ollama</option><option value="openai_compatible">OpenAI compatible / vLLM</option><option value="custom">Custom</option></select></label><label>{{t('管理地址')}}<input v-model="serviceForm.base_url" required placeholder="http://service:8000"></label><label>{{t('推理网关地址')}}<input v-model="serviceForm.gateway_url" placeholder="http://service:8000"></label><label>{{t('用途')}}<select v-model="serviceForm.role"><option value="generate">Generate</option><option value="embedding">Embedding</option><option value="rerank">Rerank</option></select></label></div><div class="hub-form"><label>{{t('关联仓库模型')}}<select v-model="repositoryModel" :aria-label="t('关联仓库模型')"><option value="">{{t('暂不关联')}}</option><option v-for="model in models" :key="model.model_id" :value="model.model_id">{{model.model_id}}</option></select></label><label v-if="repositoryModel">{{t('后端实际模型名称')}}<input v-model="servedModel" required placeholder="served-model-name"></label></div><label v-if="serviceForm.kind!=='ollama'">API contract<textarea v-model="contract" rows="12" spellcheck="false"></textarea></label><button :disabled="busy">{{t('保存')}}</button></form></details>
  </template>
  <section v-if="tab==='references'" class="panel hub-card"><h2>{{t('别名与引用')}}</h2><h3>{{t('模型别名')}}</h3><form class="hub-toolbar" @submit.prevent="createAlias"><input v-model="aliasName" required :placeholder="t('别名')"><input v-model="aliasTarget" required placeholder="hf://org/repo"><button :disabled="busy">{{t('创建别名')}}</button></form><div class="hub-file-list"><div v-for="alias in aliases" :key="alias.alias"><code>{{alias.alias}} → {{alias.target_model_id}}</code><button @click="deleteAlias(alias.alias)">{{t('删除')}}</button></div></div><h3>{{t('容器引用')}}</h3><p>{{t('已绑定的模型会阻止删除；解除引用不会停止外部容器。')}}</p><form class="hub-toolbar" @submit.prevent="bind"><input v-model="containerId" required placeholder="container_id"><input v-model="containerModel" required placeholder="hf://org/repo"><input v-model.number="containerCount" type="number" min="1" required :aria-label="t('引用计数')"><button :disabled="busy">{{t('绑定')}}</button></form><div class="hub-file-list"><div v-for="binding in bindings" :key="binding.container_id"><code>{{binding.container_id}} → {{binding.model_id}} × {{binding.ref_count}}</code><button @click="unbind(binding.container_id)">{{t('解除引用')}}</button></div></div></section>
  <ModelLifecycle v-if="tab==='lifecycle'" :t="t"/>
  <ModelHubGuide v-if="docsOnly" :t="t"/>
  <div v-if="budgetDraft" class="hub-modal-backdrop" @click.self="budgetDraft=null">
   <form class="panel hub-modal" @submit.prevent="saveBudget">
    <h2>{{t('校准模型预算')}}</h2>
    <p><code>{{budgetDraft.model_id}}</code></p>
    <p class="hub-warning" role="alert">{{budgetDraft.mode==='direct'?t('直接放行会跳过调度准入：不检查节点剩余资源、不创建模型预算，请求直接发送到 Ollama。并发过高时可能与其他任务争抢资源，仅建议在受控场景使用。'):t('手动预算会覆盖调度器按模型体积和资源采样自动估算的数值。设置过低可能导致模型启动失败或与其他任务争抢资源；设置过高会长期占用 GPU 和内存，降低并发能力。请按实测结果调整，出现异常时恢复默认预算。')}}</p>
    <div class="hub-scope"><label v-for="item in budgetModes" :key="item.id"><input v-model="budgetDraft.mode" type="radio" :value="item.id">{{t(item.label)}}</label></div>
    <div v-if="budgetDraft.mode!=='direct'" class="hub-form"><label v-for="field in resourceFields" :key="field.key">{{t(field.label)}}<input v-model.number="budgetDraft.resources[field.key]" type="number" min="0" step="1" required></label></div>
    <p v-if="budgetDraft.mode!=='direct'&&budgetDraft.default"><small>{{t('自动估算')}}: {{resourcesLabel(budgetDraft.default)}}</small></p>
   <template v-if="budgetDraft.mode!=='direct'">
    <h3 class="hub-budget-subtitle">{{t('运行上限')}}</h3>
    <p><small>{{t('运行上限约束客户端未提供或超界的上下文、线程、批量和输出 token；超过上限的请求会在调度准入前拒绝。')}}</small></p>
    <div class="hub-form"><label v-for="field in limitFields" :key="field.key">{{t(field.label)}}<input v-model.number="budgetDraft.limits[field.key]" type="number" min="0" step="1" required></label></div>
   </template>
    <label class="hub-check"><input v-model="budgetConfirm" type="checkbox">{{t('我已了解风险，确认应用该设置')}}</label>
    <div class="hub-actions"><button type="submit" :disabled="busy||!budgetConfirm">{{busy?t('保存中…'):t('保存校准')}}</button><button type="button" @click="budgetDraft=null">{{t('取消')}}</button></div>
   </form>
  </div>
 </div>
</template>
